const epCss="#hubPlane .epHero{display:flex;align-items:center;gap:12px;min-height:84px;padding:12px 14px;border:1px solid #3c6178;border-radius:16px;background:radial-gradient(ellipse at 12% 45%,#294e68 0,transparent 58%),linear-gradient(120deg,#142c40,#111e2c);margin:0 0 12px;color:#eff8ff}\n#hubPlane .epHero h2{margin:2px 0;font-size:23px}\n#hubPlane .epBrand{font-size:10px;font-weight:700;letter-spacing:1.5px;color:#9eb9cf}\n#hubPlane .epActions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin:10px 0}\n#hubPlane .epAction{min-height:40px;padding:8px 6px;border:1px solid #3b5f75;border-radius:10px;background:#1a3043;color:#e5f4ff;font-size:12px;white-space:normal;overflow-wrap:anywhere;font-weight:650}\n#hubPlane .epAction[aria-pressed=true]{border-color:#82c3f4;background:linear-gradient(130deg,#345d80,#22415e);color:#fff}\n#hubPlane .epFields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:12px 0}\n#hubPlane .epFields label{display:block;min-width:0;font-size:12px;overflow-wrap:anywhere}\n#hubPlane .epFields select{width:100%;margin-top:5px}\n#hubPlane .epBudget{padding:11px 12px;border:1px solid #34536c;border-radius:13px;background:#142637;margin:10px 0;color:#e5f4ff}\n#hubPlane .epCards{display:grid;gap:8px}\n#hubPlane .epCard{border:1px solid #395c75;border-radius:13px;background:linear-gradient(135deg,#1c344b,#152637);overflow:hidden;color:#e5f4ff}\n#hubPlane .epCard[open]{border-color:#6698bb}\n#hubPlane .epSummary{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:5px 8px;padding:10px;list-style:none;cursor:pointer}\n#hubPlane .epSummary::-webkit-details-marker{display:none}\n#hubPlane .epIdentity{display:flex;align-items:center;gap:9px;min-width:0}\n#hubPlane .epName{font-size:13px;overflow-wrap:anywhere;line-height:1.25}\n#hubPlane .epPill{font-size:11px;padding:4px 6px;max-width:95px;border-radius:7px;background:#284b66;color:#dceeff;white-space:normal;overflow-wrap:anywhere;text-align:center}\n#hubPlane .epCost{grid-column:1/-1;color:#acc9e0;font-size:11px;line-height:1.4;padding-inline-start:5px}\n#hubPlane .epBody{padding:1px 11px 11px;border-top:1px solid #35516a}\n#hubPlane .epStageTitle{display:flex;align-items:center;gap:8px;margin:12px 0 2px;color:#b1d5f3;font-size:14px}\n#hubPlane .epSprite{display:inline-block;flex:none;width:52px;max-width:100%;background-repeat:no-repeat;vertical-align:middle}\n#hubPlane .epHeroArt{width:70px}\n#hubPlane .epSmallSprite{width:27px}\n#hubPlane .epStageArt{width:31px}\n#hubPlane .epSkinCardArt{width:73px}\n#hubPlane .epResourceLabel{display:flex;align-items:center;gap:5px;min-width:0;overflow-wrap:anywhere}\n#hubPlane .epCompare{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}\n#hubPlane .epPreview{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:124px;gap:5px;padding:7px;min-width:0;border:1px solid #3c5f78;border-radius:12px;background:radial-gradient(ellipse at center,#26465e,transparent 72%),#112131;color:#dceeff;text-align:center}\n#hubPlane .epPreviewArt{width:min(100%,160px)}\n#hubPlane .epPreview small{color:#bed7ea;font-size:11px;overflow-wrap:anywhere}\n#hubPlane .epDescription,#hubPlane .epSmall{font-size:12px;line-height:1.5;overflow-wrap:anywhere}\n#hubPlane .epSmall{opacity:.86}\n#hubPlane .epBreakdown{margin-top:9px;padding:8px;border:1px solid #35566d;border-radius:9px}\n#hubPlane .epBreakdown summary{cursor:pointer;font-size:12px}\n#hubPlane .epStep{padding:5px 2px;border-bottom:1px solid #35516a;font-size:12px;line-height:1.4;overflow-wrap:anywhere}\n#hubPlane .epStep:last-child{border-bottom:0}\n@media(min-width:650px){#hubPlane .epActions{grid-template-columns:repeat(3,minmax(0,1fr))}}\n";
function planeSprite(node,key,cls=''){
 const a=planeArtMap[String(key)];if(!a)return null;
 const [sheet,x,y,w,h,sw,sh]=a,el=node('span','epSprite '+cls);el.setAttribute('aria-hidden','true');el.dataset.planeArt=String(key);
 el.style.aspectRatio=w+' / '+h;el.style.backgroundImage='url("assets/planes/plane-'+sheet+'.webp?v=0.7.95")';el.style.backgroundSize=(100*sw/w)+'% '+(100*sh/h)+'%';el.style.backgroundPosition=(sw===w?0:100*x/(sw-w))+'% '+(sh===h?0:100*y/(sh-h))+'%';return el
}
function planeResourceId(label,t,u){return new Map([[t[7],67240388],[t[8],67240389],[u[0],67240390],[u[1],67240456],[u[2],67240457],[u[3],67240458]]).get(label)||null}
function planeAppendArt(parent,node,key,cls=''){const art=planeSprite(node,key,cls);if(art)parent.append(art)}
function planeCompareVisual(node,items){const wrap=node('div','epCompare');for(const q of items){const card=node('div','epPreview');planeAppendArt(card,node,q.art,'epPreviewArt');const cap=node('small','',q.label);if(q.badge){const row=node('span','epResourceLabel');planeAppendArt(row,node,q.badge,'epSmallSprite');row.append(cap);card.append(row)}else card.append(cap);wrap.append(card)}return wrap}
function planeBasePreview(node,states,t){const stage=n=>Math.min(8,Math.floor(n/10)+1);return planeCompareVisual(node,states[1].map((n,i)=>({art:'base_'+stage(n),badge:'stage_'+stage(n),label:t[i?3:2]+' · '+t[6]+' '+stage(n)})))}

